	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                              // PIC X len=1 = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0)      // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0) // PIC 9(8)V99 len=10 = 0
var WsCount int64 = 0                                   // PIC 9(3) len=3 = 0
var WsPriceEd string                                     // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string                                      // PIC ZZ,ZZ9.99 len=9
var WsNetEd string                                       // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string                                     // PIC ZZ,ZZZ,ZZ9.99 len=13

var DiscRecGlobal DiscRec

var fileDisc *os.File
var scannerDisc *bufio.Scanner
var eofDisc bool

func inputDone() bool { return WsEofFlag == "Y" }
func setInputDone(v bool) {
	if v {
		WsEofFlag = "Y"
	} else {
		WsEofFlag = "N"
	}
}

// Helpers for overflow / store
func pow10(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}
func pow10Decimal(n int) decimal.Decimal {
	return decimal.NewFromInt(pow10(n))
}

// storeDecimal truncates to scale and drops high-order integer digits that don't fit
func storeDecimal(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	// Truncate toward zero to scale
	v := val.Truncate(int32(scale))
	// Handle overflow: keep low-order integer digits
	// Determine sign
	neg := v.Sign() < 0
	if neg {
		v = v.Neg()
	}
	// split
	// integer part
	intPart := v.Truncate(0)
	frac := v.Sub(intPart)
	// overflow on integer part
	if intDigits < 18 {
		mod := pow10(intDigits)
		// intPart may be large; use decimal modulo via IntPart?
		// decimal has Mod? use Div and truncate
		// compute intPart % mod using big int via decimal
		// decimal.Mod not available in older version; implement via integer division
		// intPart is non-negative and scale 0
		// q = intPart.Div(decimal.NewFromInt(mod)).Truncate(0)
		// r = intPart - q*mod
		modDec := decimal.NewFromInt(mod)
		q := intPart.Div(modDec).Truncate(0)
		r := intPart.Sub(q.Mul(modDec))
		intPart = r
		v = intPart.Add(frac)
	}
	if neg {
		v = v.Neg()
	}
	return v
}

func formatNumericUneditedInt(val int64, digits int) string {
	if digits <= 0 {
		return ""
	}
	mod := pow10(digits)
	// keep low-order digits, handle negative? keep sign? not needed
	u := val % mod
	if u < 0 {
		u = -u
	}
	// zero padded
	return fmt.Sprintf("%0*d", digits, u)
}

func formatEdited(picture string, val decimal.Decimal) string {
	// picture contains Z,9,',','.'
	dotIdx := strings.Index(picture, ".")
	scale := 0
	intPic := picture
	fracPic := ""
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
		scale = len(fracPic) // count of 9's after dot (all are 9 in this program)
	}
	// count integer digit placeholders
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	// Prepare truncated value
	v := val.Truncate(int32(scale))
	neg := v.Sign() < 0
	if neg {
		v = v.Neg()
	}
	// overflow handling for edited: high-order digits dropped
	if intDigits > 0 {
		intPart := v.Truncate(0)
		frac := v.Sub(intPart)
		mod := decimal.NewFromInt(pow10(intDigits))
		// keep low-order
		// Use same mod logic
		q := intPart.Div(mod).Truncate(0)
		r := intPart.Sub(q.Mul(mod))
		intPart = r
		v = intPart.Add(frac)
	}
	// Build integer digits string zero padded to intDigits
	intPart := v.Truncate(0)
	// get integer as int64 maybe big; use decimal string
	// Ensure we have enough digits: format with 0 padding
	intStr := intPart.StringFixed(0) // no decimal
	// intStr may be like "0" ; pad
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	} else if len(intStr) > intDigits {
		// overflow already handled, but keep last digits
		intStr = intStr[len(intStr)-intDigits:]
	}
	// fractional digits
	fracStr := ""
	if scale > 0 {
		// get fractional part as scaled integer
		// v = intPart + frac ; frac = v - intPart
		frac := v.Sub(intPart)
		// scale factor
		scaleDec := decimal.NewFromInt(pow10(scale))
		fracScaled := frac.Mul(scaleDec).Truncate(0)
		fracInt := fracScaled.IntPart()
		fracStr = fmt.Sprintf("%0*d", scale, fracInt)
	}

	// Build output array from picture
	out := []rune(picture)
	// Map integer placeholder indices
	// We'll fill integer placeholders left to right with intStr digits
	idxDigit := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			// map to out position i
			if idxDigit < len(intStr) {
				out[i] = rune(intStr[idxDigit])
			} else {
				out[i] = '0'
			}
			idxDigit++
		} else {
			// comma stays
		}
	}
	// Fill fractional placeholders after dot
	if scale > 0 {
		for i := 0; i < len(fracPic); i++ {
			pos := dotIdx + 1 + i
			if i < len(fracStr) {
				out[pos] = rune(fracStr[i])
			} else {
				out[pos] = '0'
			}
		}
	}
	// Apply Z suppression on integer part
	// intPic area is 0 .. dotIdx-1 (if dot exists) else whole
	suppressing := true
	for i := 0; i < len(intPic); i++ {
		pch := intPic[i] // original picture char
		if pch == 'Z' {
			if suppressing && out[i] == '0' {
				out[i] = ' '
			} else {
				suppressing = false
			}
		} else if pch == '9' {
			// never suppress, ends suppression
			suppressing = false
		} else if pch == ',' {
			// leave for now, will handle after
		}
	}
	// Commas inside suppressed zone become spaces
	// For each comma position, if all digit placeholders to its left are spaces (i.e., suppressed), comma becomes space
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == ',' {
			// check if any digit placeholder to left is not blank
			hasNonBlankLeft := false
			for j := 0; j < i; j++ {
				if intPic[j] == 'Z' || intPic[j] == '9' {
					if out[j] != ' ' {
						hasNonBlankLeft = true
						break
					}
				}
			}
			if !hasNonBlankLeft {
				out[i] = ' '
			}
		}
	}
	if neg {
		// COBOL would show sign; not needed for positive data
	}
	return string(out)
}

func readDiscRec() {
	if scannerDisc == nil {
		setInputDone(true)
		return
	}
	if !scannerDisc.Scan() {
		// check error?
		setInputDone(true)
		return
	}
	line := scannerDisc.Text()
	// LINE SEQUENTIAL: if shorter than record length (15), pad with spaces on right
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// Parse fields
	drItem := line[0:6]
	drPriceStr := line[6 : 6+7]
	drPctStr := line[13 : 13+2]

	DiscRecGlobal.DrItem = drItem

	// DR-PRICE PIC 9(5)V99 digits only
	s := strings.TrimSpace(drPriceStr)
	if s == "" {
		s = "0"
	}
	// Keep digits only
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		digits = "0"
	}
	// parse as integer
	n := decimal.NewFromInt(0)
	// use decimal to avoid overflow; parse via string
	// Build via decimal
	// Since up to 7 digits fits int64, we can parse int64
	var iv int64
	fmt.Sscanf(digits, "%d", &iv)
	// alternative: use decimal.NewFromString
	// Use New with shift -2
	DiscRecGlobal.DrPrice = decimal.New(iv, -2)

	// DR-PCT PIC 9(2)
	t := strings.TrimSpace(drPctStr)
	if t == "" {
		t = "0"
	}
	var pv int64
	fmt.Sscanf(t, "%d", &pv)
	DiscRecGlobal.DrPct = pv
}

func MAINPARA() {
	fileDisc, _ = os.Open("input.dat")
	if fileDisc != nil {
		scannerDisc = bufio.NewScanner(fileDisc)
		// Allow long lines
		scannerDisc.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	} else {
		setInputDone(true)
		scannerDisc = nil
	}
	READPARA()
	for !inputDone() {
		PROCESSPARA()
	}
	if fileDisc != nil {
		fileDisc.Close()
	}
	SUMMARYPARA()
}

func READPARA() {
	if eofDisc {
		setInputDone(true)
		return
	}
	if scannerDisc == nil {
		setInputDone(true)
		return
	}
	// If EOF already flagged, do nothing
	if inputDone() {
		return
	}
	readDiscRec()
	if inputDone() {
		eofDisc = true
	}
}

func PROCESSPARA() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	prod := DiscRecGlobal.DrPrice.Mul(decimal.NewFromInt(DiscRecGlobal.DrPct))
	div := prod.Shift(-2) // divide by 100
	rounded := div.Round(2)
	WsDiscount = storeDecimal(rounded, 5, 2)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	net := DiscRecGlobal.DrPrice.Sub(WsDiscount)
	WsNet = storeDecimal(net, 5, 2)

	// ADD WS-NET TO WS-TOTAL-NET
	sum := WsTotalNet.Add(WsNet)
	WsTotalNet = storeDecimal(sum, 8, 2)

	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % pow10(3) // keep low-order 3 digits

	// MOVE DR-PRICE TO WS-PRICE-ED etc.
	WsPriceEd = formatEdited("ZZ,ZZ9.99", DiscRecGlobal.DrPrice)
	WsDiscEd = formatEdited("ZZ,ZZ9.99", WsDiscount)
	WsNetEd = formatEdited("ZZ,ZZ9.99", WsNet)

	// DISPLAY DR-ITEM " " WS-PRICE-ED " " DR-PCT "% " WS-DISC-ED " " WS-NET-ED
	pctStr := formatNumericUneditedInt(DiscRecGlobal.DrPct, 2)
	line := DiscRecGlobal.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Println(line)

	READPARA()
}

func SUMMARYPARA() {
	WsTotalEd = formatEdited("ZZ,ZZZ,ZZ9.99", WsTotalNet)
	countStr := formatNumericUneditedInt(WsCount, 3)
	line := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Println(line)
}

func main() {
	MAINPARA()
}

